import{_ as n,c as h,o as i,a2 as a}from"./chunks/framework.B7el9cAC.js";const e=JSON.parse('{"title":"Mục 3.2 – Giới hạn của AI","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-3/3.2-gioi-han-ai.md","filePath":"chuong-3/3.2-gioi-han-ai.md","lastUpdated":1774578382000}'),o={name:"chuong-3/3.2-gioi-han-ai.md"};function g(c,t,r,u,s,l){return i(),h("div",null,[...t[0]||(t[0]=[a('<h1 id="muc-3-2-–-gioi-han-cua-ai" tabindex="-1">Mục 3.2 – Giới hạn của AI <a class="header-anchor" href="#muc-3-2-–-gioi-han-cua-ai" aria-label="Permalink to &quot;Mục 3.2 – Giới hạn của AI&quot;">​</a></h1><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><p>Bạn đã bao giờ hỏi ChatGPT một câu hỏi và nhận được câu trả lời <strong>nghe rất tự tin nhưng hoàn toàn sai</strong>? Hay thấy AI tạo ảnh nhân vật có <strong>sáu ngón tay</strong>? Hoặc AI dịch câu &quot;Tôi đói bụng quá&quot; sang tiếng Anh thành &quot;I am very hungry stomach&quot;?</p><p>Những điều đó xảy ra vì AI <strong>không phải là con người</strong>, dù đôi khi trông giống vậy. AI có những giới hạn rõ ràng mà chúng ta cần hiểu để sử dụng đúng cách và không bị phụ thuộc mù quáng.</p><p><strong>Tại sao cần biết giới hạn của AI?</strong> Hiểu giới hạn của AI giúp bạn:</p><ul><li>Không tin tưởng AI 100% trong mọi tình huống</li><li>Biết khi nào nên dùng AI, khi nào không</li><li>Tránh bị lừa bởi thông tin sai từ AI</li><li>Trở thành người dùng công nghệ thông minh</li></ul><p><strong>Ví dụ đời thực:</strong></p><ul><li>🏠 <strong>Tại nhà:</strong> Loa thông minh không hiểu &quot;mở đèn cái kia&quot; vì &quot;cái kia&quot; không có ngữ cảnh rõ ràng.</li><li>☕ <strong>Tại quán cafe:</strong> Chatbot hỗ trợ khách không hiểu khi khách bực bội và nói mỉa mai: &quot;Ừ, ngon lắm đấy!&quot; (thực ra đang phàn nàn).</li><li>🏫 <strong>Tại trường:</strong> AI chấm bài có thể cho điểm cao bài viết sai nội dung nhưng đúng ngữ pháp và từ vựng hay.</li></ul><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="gioi-han-1-ai-khong-co-cam-xuc-that" tabindex="-1">Giới hạn 1: AI không có cảm xúc thật <a class="header-anchor" href="#gioi-han-1-ai-khong-co-cam-xuc-that" aria-label="Permalink to &quot;Giới hạn 1: AI không có cảm xúc thật&quot;">​</a></h3><p>AI <strong>không cảm nhận</strong> được vui, buồn, tức giận, hay đồng cảm. Khi ChatGPT viết &quot;Tôi hiểu bạn đang buồn&quot;, đó chỉ là một chuỗi từ được tạo ra dựa trên xác suất thống kê từ dữ liệu huấn luyện — không phải sự đồng cảm thật sự.</p><p><strong>Tại sao AI trông có vẻ có cảm xúc?</strong> Vì AI được huấn luyện trên hàng triệu văn bản của con người có biểu đạt cảm xúc. AI học cách <strong>bắt chước ngôn ngữ cảm xúc</strong>, không phải cảm nhận cảm xúc.</p><h3 id="gioi-han-2-ai-khong-co-hieu-biet-thuong-thuc-that-su-common-sense" tabindex="-1">Giới hạn 2: AI không có hiểu biết thường thức thật sự (Common Sense) <a class="header-anchor" href="#gioi-han-2-ai-khong-co-hieu-biet-thuong-thuc-that-su-common-sense" aria-label="Permalink to &quot;Giới hạn 2: AI không có hiểu biết thường thức thật sự (Common Sense)&quot;">​</a></h3><p><strong>Common sense</strong> là những hiểu biết mà con người tự nhiên có mà không cần học: &quot;Nước đổ xuống&quot;, &quot;Dao sắc thì nguy hiểm&quot;, &quot;Người ngủ thì không nói chuyện được&quot;.</p><p>AI có thể trả lời sai những câu hỏi hiển nhiên với người thường, ví dụ:</p><ul><li>Hỏi: &quot;Tôi cầm một cái trứng và thả tay ra. Trứng ở đâu?&quot; → AI đôi khi trả lời sai vì không thật sự hiểu vật lý trong thế giới thực.</li></ul><h3 id="gioi-han-3-ai-khong-sang-tao-that-su" tabindex="-1">Giới hạn 3: AI không sáng tạo thật sự <a class="header-anchor" href="#gioi-han-3-ai-khong-sang-tao-that-su" aria-label="Permalink to &quot;Giới hạn 3: AI không sáng tạo thật sự&quot;">​</a></h3><p>AI <strong>tổng hợp</strong> dữ liệu cũ chứ không <strong>phát minh</strong> điều mới. Khi AI vẽ một bức tranh &quot;sáng tạo&quot;, thực chất nó đang kết hợp các mẫu hình đã thấy trong hàng triệu ảnh huấn luyện. Nó không có trải nghiệm sống, không có cảm xúc thúc đẩy sáng tác như nghệ sĩ thật.</p><h3 id="gioi-han-4-ai-co-the-ao-giac-hallucination" tabindex="-1">Giới hạn 4: AI có thể &quot;ảo giác&quot; (Hallucination) <a class="header-anchor" href="#gioi-han-4-ai-co-the-ao-giac-hallucination" aria-label="Permalink to &quot;Giới hạn 4: AI có thể &quot;ảo giác&quot; (Hallucination)&quot;">​</a></h3><p>AI đôi khi <strong>bịa ra thông tin</strong> một cách tự tin — hiện tượng này gọi là <strong>hallucination</strong>. Ví dụ: AI có thể bịa ra tên tác giả, tiêu đề sách, hoặc số liệu thống kê không tồn tại.</p><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="thuc-chat-ai-thieu-gi" tabindex="-1">Thực chất AI thiếu gì? <a class="header-anchor" href="#thuc-chat-ai-thieu-gi" aria-label="Permalink to &quot;Thực chất AI thiếu gì?&quot;">​</a></h3><p>Hãy tưởng tượng một người <strong>chưa bao giờ ra ngoài đời thực</strong>, chỉ đọc sách. Người đó có thể biết nhiều lý thuyết, viết văn hay, trả lời câu hỏi thông minh — nhưng sẽ rất lúng túng khi đối mặt với thực tế: không biết mùi của mưa, không hiểu tại sao người ta khóc khi nghe bài hát quen, không biết cảm giác đói thật sự là gì.</p><p><strong>AI chính là người đó.</strong> AI học từ văn bản và dữ liệu, nhưng không có thân xác, không có trải nghiệm, không có cảm xúc sống.</p><h3 id="tai-sao-ai-ao-giac" tabindex="-1">Tại sao AI &quot;ảo giác&quot;? <a class="header-anchor" href="#tai-sao-ai-ao-giac" aria-label="Permalink to &quot;Tại sao AI &quot;ảo giác&quot;?&quot;">​</a></h3><p>Mô hình ngôn ngữ AI hoạt động bằng cách dự đoán từ tiếp theo có khả năng xuất hiện nhất. Khi không có đủ thông tin, thay vì nói &quot;Tôi không biết&quot;, AI vẫn tiếp tục tạo ra từ ngữ có vẻ hợp lý — và đó là lúc nó bịa ra thông tin sai.</p><h3 id="tai-sao-ai-khong-co-common-sense-that" tabindex="-1">Tại sao AI không có common sense thật? <a class="header-anchor" href="#tai-sao-ai-khong-co-common-sense-that" aria-label="Permalink to &quot;Tại sao AI không có common sense thật?&quot;">​</a></h3><p>Common sense của con người đến từ hàng nghìn năm tiến hóa và hàng chục năm trải nghiệm thực tế. AI chỉ học từ văn bản — không có cơ thể để biết đau, không có giác quan để biết nóng lạnh, không có xã hội để học cách ứng xử thực sự.</p><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="tai-sao-ai-đua-ra-thong-tin-sai" tabindex="-1">Tại sao AI đưa ra thông tin sai? <a class="header-anchor" href="#tai-sao-ai-đua-ra-thong-tin-sai" aria-label="Permalink to &quot;Tại sao AI đưa ra thông tin sai?&quot;">​</a></h3><ol><li><strong>Người dùng đặt câu hỏi</strong> về một chủ đề ít phổ biến.</li><li><strong>Mô hình AI tìm kiếm</strong> trong dữ liệu huấn luyện — nhưng dữ liệu không đầy đủ.</li><li><strong>Thuật toán dự đoán</strong> từ tiếp theo dựa trên xác suất thống kê.</li><li><strong>Không có cơ chế &quot;biết mình không biết&quot;</strong> — AI tiếp tục tạo ra câu trả lời.</li><li><strong>Kết quả là hallucination</strong> — câu trả lời nghe hợp lý nhưng sai thực tế.</li><li><strong>Người dùng bị đánh lừa</strong> nếu không kiểm chứng.</li></ol><h3 id="tai-sao-ai-khong-hieu-mia-mai" tabindex="-1">Tại sao AI không hiểu mỉa mai? <a class="header-anchor" href="#tai-sao-ai-khong-hieu-mia-mai" aria-label="Permalink to &quot;Tại sao AI không hiểu mỉa mai?&quot;">​</a></h3><ol><li>Người dùng viết: &quot;Ừ, dịch vụ của các bạn tuyệt vời lắm nhé.&quot; (mỉa mai)</li><li>AI <strong>phân tích từng từ</strong>: &quot;tuyệt vời&quot; = tích cực.</li><li>AI <strong>không đọc được ngữ điệu, ngữ cảnh thực tế</strong>, hoặc lịch sử hội thoại dài.</li><li>AI phân loại câu này là <strong>phản hồi tích cực</strong>.</li><li><strong>Kết quả sai</strong>: AI trả lời &quot;Cảm ơn bạn đã tin tưởng!&quot; trong khi khách đang phàn nàn.</li></ol><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-ai-khong-hieu-cau-đua" tabindex="-1">Ví dụ 1 – Cơ bản: AI không hiểu câu đùa <a class="header-anchor" href="#vi-du-1-–-co-ban-ai-khong-hieu-cau-đua" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: AI không hiểu câu đùa&quot;">​</a></h3><p>Hỏi ChatGPT: &quot;Tại sao con gà qua đường?&quot; (câu đố vui kinh điển)</p><p>AI có thể trả lời nghiêm túc: &quot;Con gà qua đường vì nó muốn tìm thức ăn ở phía bên kia&quot; — thay vì hiểu đây là một câu đố có đáp án hài hước theo quy ước văn hóa.</p><p>→ <strong>Giới hạn:</strong> AI không hiểu hài hước và ngữ cảnh văn hóa ngầm định.</p><h3 id="vi-du-2-–-đoi-thuc-ai-bia-nguon-trich-dan" tabindex="-1">Ví dụ 2 – Đời thực: AI bịa nguồn trích dẫn <a class="header-anchor" href="#vi-du-2-–-đoi-thuc-ai-bia-nguon-trich-dan" aria-label="Permalink to &quot;Ví dụ 2 – Đời thực: AI bịa nguồn trích dẫn&quot;">​</a></h3><p>Một sinh viên nhờ ChatGPT tìm tài liệu tham khảo về một chủ đề nghiên cứu. AI cung cấp danh sách 5 bài báo khoa học với tên tác giả, tiêu đề, và năm xuất bản. Khi sinh viên tìm kiếm, <strong>3 trong 5 bài báo đó không tồn tại</strong> — AI đã bịa hoàn toàn.</p><p>→ <strong>Giới hạn:</strong> Hallucination — AI tự tin cung cấp thông tin sai.</p><h3 id="vi-du-3-–-nang-cao-ai-that-bai-trong-tinh-huong-can-đong-cam-thuc-su" tabindex="-1">Ví dụ 3 – Nâng cao: AI thất bại trong tình huống cần đồng cảm thực sự <a class="header-anchor" href="#vi-du-3-–-nang-cao-ai-that-bai-trong-tinh-huong-can-đong-cam-thuc-su" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: AI thất bại trong tình huống cần đồng cảm thực sự&quot;">​</a></h3><p>Một người đang rất buồn vì mất người thân nhắn tin cho chatbot hỗ trợ tâm lý AI. AI đưa ra các câu trả lời chuẩn mực về đau buồn theo sách vở, nhưng không nhận ra được khi người dùng dùng ngôn ngữ ẩn ý về ý định tự làm hại bản thân — vì AI không thật sự hiểu cảm xúc mà chỉ nhận dạng từ khóa.</p><p>→ <strong>Giới hạn nghiêm trọng:</strong> Thiếu cảm xúc và common sense trong tình huống nhạy cảm có thể gây nguy hiểm.</p><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="ai-vs-con-nguoi" tabindex="-1">AI vs Con người <a class="header-anchor" href="#ai-vs-con-nguoi" aria-label="Permalink to &quot;AI vs Con người&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>AI</th><th>Con người</th></tr></thead><tbody><tr><td>Cảm xúc</td><td>Không có (bắt chước ngôn ngữ cảm xúc)</td><td>Có cảm xúc thật sự</td></tr><tr><td>Common sense</td><td>Yếu, dễ sai với tình huống thực tế</td><td>Mạnh, học từ trải nghiệm sống</td></tr><tr><td>Sáng tạo</td><td>Tổng hợp mẫu cũ</td><td>Có thể phát minh hoàn toàn mới</td></tr><tr><td>Tốc độ xử lý</td><td>Rất nhanh</td><td>Chậm hơn</td></tr><tr><td>Xử lý dữ liệu lớn</td><td>Rất tốt</td><td>Hạn chế</td></tr><tr><td>Nhận biết ngữ cảnh xã hội</td><td>Yếu</td><td>Mạnh</td></tr><tr><td>Mệt mỏi</td><td>Không</td><td>Có</td></tr><tr><td>Học từ trải nghiệm thực tế</td><td>Không (chỉ học từ dữ liệu số)</td><td>Có</td></tr></tbody></table><h3 id="cac-loai-gioi-han-cua-ai" tabindex="-1">Các loại giới hạn của AI <a class="header-anchor" href="#cac-loai-gioi-han-cua-ai" aria-label="Permalink to &quot;Các loại giới hạn của AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Loại giới hạn</th><th>Mô tả</th><th>Hậu quả nếu bỏ qua</th></tr></thead><tbody><tr><td>Thiếu cảm xúc</td><td>Không đồng cảm thật</td><td>Tư vấn tâm lý nguy hiểm</td></tr><tr><td>Thiếu common sense</td><td>Sai trong tình huống đơn giản</td><td>Quyết định sai lầm</td></tr><tr><td>Thiếu sáng tạo thật</td><td>Chỉ remix dữ liệu cũ</td><td>Nội dung thiếu độc đáo</td></tr><tr><td>Hallucination</td><td>Bịa thông tin tự tin</td><td>Tin vào thông tin sai</td></tr><tr><td>Thiếu cập nhật</td><td>Dữ liệu có cutoff date</td><td>Thông tin lỗi thời</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>AI <strong>không có cảm xúc thật</strong> — chỉ bắt chước ngôn ngữ cảm xúc từ dữ liệu</li><li>AI <strong>thiếu common sense</strong> — không có trải nghiệm thực tế từ thế giới vật lý</li><li>AI <strong>không sáng tạo thật</strong> — tổng hợp và tái kết hợp mẫu cũ, không phát minh mới</li><li><strong>Hallucination</strong> = AI bịa thông tin sai nhưng trình bày tự tin</li><li>AI giỏi: xử lý dữ liệu lớn, tốc độ cao, nhất quán không mệt mỏi</li><li>Con người giỏi hơn AI: đồng cảm thật, common sense, sáng tạo đột phá, đạo đức</li><li><strong>Không nên</strong> dùng AI để đưa ra quyết định y tế, pháp lý, tâm lý mà không có chuyên gia kiểm tra</li><li>Luôn <strong>kiểm chứng</strong> thông tin AI cung cấp trước khi sử dụng</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><p><strong>Câu 1 (Dễ):</strong> &quot;Hallucination&quot; trong AI là gì? Cho một ví dụ cụ thể.</p><blockquote><p><strong>Đáp án:</strong> Hallucination là hiện tượng AI tạo ra thông tin sai nhưng nghe tự tin và hợp lý. Ví dụ: AI bịa ra tên một cuốn sách không tồn tại, kèm tên tác giả và năm xuất bản giả mạo.</p></blockquote><hr><p><strong>Câu 2 (Dễ):</strong> Tại sao nói AI &quot;không có common sense thật sự&quot;? Giải thích bằng một ví dụ.</p><blockquote><p><strong>Đáp án:</strong> AI học từ văn bản, không có trải nghiệm thực tế. Ví dụ: AI biết định nghĩa của &quot;lửa nóng&quot; nhưng không &quot;biết&quot; cảm giác bỏng tay — nó có thể đưa ra lời khuyên về lửa mà thiếu sự thận trọng mà người có kinh nghiệm thực tế tự nhiên sẽ có.</p></blockquote><hr><p><strong>Câu 3 (Trung bình):</strong> Một công ty muốn dùng AI để tư vấn tâm lý cho học sinh. Hãy nêu 2 giới hạn của AI khiến điều này có thể gây nguy hiểm.</p><blockquote><p><strong>Đáp án:</strong></p><ol><li><strong>Thiếu cảm xúc thật:</strong> AI không thật sự đồng cảm — có thể phản hồi không phù hợp khi học sinh trong tình trạng khủng hoảng nghiêm trọng.</li><li><strong>Thiếu common sense và nhận biết ngữ cảnh:</strong> AI có thể không nhận ra các dấu hiệu ngầm của trạng thái nguy hiểm nếu học sinh dùng cách diễn đạt gián tiếp hoặc ẩn ý.</li></ol></blockquote><hr><p><strong>Câu 4 (Trung bình):</strong> So sánh sự khác biệt giữa &quot;AI sáng tạo&quot; và &quot;Con người sáng tạo&quot; theo 3 tiêu chí.</p><blockquote><p><strong>Đáp án:</strong></p><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>AI</th><th>Con người</th></tr></thead><tbody><tr><td>Nguồn gốc ý tưởng</td><td>Kết hợp mẫu từ dữ liệu cũ</td><td>Từ cảm xúc, trải nghiệm, trực giác</td></tr><tr><td>Khả năng đột phá</td><td>Hạn chế (trong phạm vi dữ liệu đã học)</td><td>Có thể tạo ra điều hoàn toàn mới</td></tr><tr><td>Động lực sáng tạo</td><td>Không có (thực hiện theo yêu cầu)</td><td>Đến từ đam mê, nhu cầu biểu đạt</td></tr></tbody></table></blockquote><hr><p><strong>Câu 5 (Ứng dụng):</strong> Bạn được giao viết báo cáo về lịch sử Việt Nam và dùng AI để tìm số li���u. AI cung cấp 10 con số thống kê. Bạn sẽ làm gì và tại sao?</p><blockquote><p><strong>Đáp án gợi ý:</strong> Không nên dùng trực tiếp. Cần:</p><ol><li><strong>Kiểm chứng từng số liệu</strong> bằng nguồn uy tín (sách giáo khoa, trang web chính phủ, báo chính thống).</li><li><strong>Tìm nguồn gốc cụ thể</strong> cho mỗi con số — AI không luôn cung cấp nguồn trích dẫn chính xác.</li><li><strong>Lý do:</strong> AI có thể hallucinate — bịa ra số liệu nghe hợp lý nhưng sai. Trong báo cáo học thuật, dùng số liệu sai là rủi ro nghiêm trọng về học thuật và uy tín.</li></ol></blockquote><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lỗi thường gặp</th><th>Cách hiểu đúng</th></tr></thead><tbody><tr><td>Tin AI 100% vì nó &quot;nghe tự tin&quot;</td><td>Mức độ tự tin trong ngôn ngữ của AI không phản ánh độ chính xác. AI có thể sai rất tự tin.</td></tr><tr><td>Nghĩ AI &quot;đồng cảm&quot; khi nó nói &quot;Tôi hiểu bạn&quot;</td><td>Đó chỉ là chuỗi từ xác suất cao — không phải cảm xúc thật.</td></tr><tr><td>Dùng AI viết bài luận sáng tạo và nghĩ đó là ý tưởng của mình</td><td>Bài do AI viết là tổng hợp từ triệu văn bản khác — không phải tư duy sáng tạo của bạn.</td></tr><tr><td>Cho rằng AI &quot;không biết&quot; thì sẽ nói &quot;Tôi không biết&quot;</td><td>Không đúng — AI thường tạo ra câu trả lời dù không có đủ thông tin. Phải chủ động kiểm chứng.</td></tr><tr><td>Nghĩ giới hạn của AI sẽ không bao giờ cải thiện</td><td>Sai — AI đang tiến bộ nhanh, nhưng những giới hạn cơ bản (cảm xúc thật, trải nghiệm thực tế) vẫn là thách thức lớn chưa giải quyết được.</td></tr></tbody></table>',77)])])}const m=n(o,[["render",g]]);export{e as __pageData,m as default};
